// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points, acceptedAnswers}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    if (acceptedAnswers && (!acceptedAnswers.includes(answer) || new Set(acceptedAnswers).size !== acceptedAnswers.length ||
        !acceptedAnswers.every(index => Number.isInteger(index) && index >= 0 && index < choices.length))) {
      throw new Error('Invalid accepted answers in ' + year + '/' + grade + '/' + (index + 1));
    }
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(acceptedAnswers ? {acceptedAnswers} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const tokens = step === 3 ? (lessons[i].acceptedAnswers ?? [letters.indexOf(key)]).map(index => {
        const result = lessons[i].choices[index].replace(/^\[(.*)\][.]?$/, '$1');
        return letters[index] + (result ? ' · ' + result : '');
      }) : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2009, "10-11", [{"author":"И. Иткин и Т. Козлова","question":"В изложении ученик написал: «<em>Все восхищались этим поэтом, его творчество возводили в куб</em>». А как надо было написать?","choices":["именно так и надо было","<em>...возводили в квадрат</em>","...<em>возводили в круг</em>","...<em>возводили в куль</em>","...<em>возводили в культ</em>."],"key":"Д","review":["Слово в устойчивом обороте","Представь, что творчество поэта почитают почти как предмет поклонения. Вспомни слово для такого почитания.","Говорят «возводить в культ». «Культ» обозначает преклонение или чрезмерное почитание."]},{"author":"И. Иткин","question":"В какой из этих пар слова связаны между собой по смыслу не так, как в остальных?","choices":["<em>милый</em> — <em>премилый</em>","<em>подобный</em> — <em>преподобный</em>","<em>скверный</em> — <em>прескверный</em>","<em>скучный</em> — <em>прескучный</em>","во всех этих парах слова связаны между собой одинаково."],"key":"Б","review":["Два значения приставки","Сравни «пре-» со словом «очень». Проверь, можно ли так объяснить каждое из образованных слов.","«Премилый», «прескверный» и «прескучный» усиливают признак. «Преподобный» имеет особое церковное значение и не означает «очень подобный»."]},{"author":"Н. Валеева","question":"Страшная сила, которая требует жертв и спасёт мир, — это:","choices":["искусство","вера","наука","мудрость","красота."],"key":"Д","review":["Три знакомые фразы","Попробуй восстановить выражения «страшная сила», «требует жертв» и «спасёт мир» с одним и тем же подлежащим.","Все три оборота связывают с красотой. Именно это слово завершает набор шутливо соединённых высказываний."]},{"author":"И. Иткин","question":"Какое словосочетание по смыслу лишнее?","choices":["<em>жалобный визг</em>","<em>жалобное мяуканье</em>","<em>жалобная книга</em>","<em>жалобный рассказ</em>","<em>жалобная песня</em>."],"key":"В","review":["Значения слова «жалобный»","Проверь, передаёт ли предмет жалобный звук или печальный рассказ. Одна вещь предназначена для записи жалоб.","«Жалобная книга» — книга для жалоб. Визг, мяуканье, рассказ и песня сами выражают жалобу или звучат печально."]},{"author":"Б. Иомдин","question":"Какого слова не существует?","choices":["<em>каковой</em>","<em>какаовый</em>","<em>кое-каковой</em>","<em>кое-какой</em>","<em>какой-никакой</em>."],"key":"В","review":["Формы вопросительного слова","Сравни книжное «каковой» и неопределённые слова с «кое-» или повтором «какой».","«Каковой», «кое-каковой», «кое-какой» и «какой-никакой» употребляются. Слова «какаовый» нет."]},{"author":"Н. Валеева","question":"Какое из данных ниже слов ни в одном из своих значений не связано по смыслу с идеей лишнего веса?","choices":["<em>полнота</em>","<em>полный</em>","<em>полнеть</em>","<em>пополнение</em>","<em>располневший</em>."],"key":"Г","review":["Вес и изменение количества","Подбери примеры с весом человека. Одно существительное описывает прибавление количества или приход новых людей.","«Пополнение» может быть пополнением команды, запасов или бюджета. Значение лишнего веса у этого слова отсутствует."]},{"author":"Б. Иомдин","question":"Какая из этих частиц гораздо чаще других встречается в научных текстах?","choices":["<em>аж</em>","<em>ан</em>","<em>ведь</em>","<em>ишь</em>","<em>небось</em>."],"key":"В","review":["Частица и аргумент","Найди слово, которым удобно начинать пояснение или обоснование вывода в научном тексте.","«Ведь» вводит известное основание или пояснение. Другие частицы в списке чаще употребляются в разговорной речи."]},{"author":"И. Иткин","question":"Даны существительные: <em>ропот</em>, <em>рокот</em>, <em>хохот</em>, <em>грохот</em>, <em>лепет</em>. К каждому из них можно подобрать однокоренной глагол, но одно из существительных соотносится с глаголом не совсем так, как остальные четыре. Какое это существительное?","choices":["<em>ропот</em>","<em>рокот</em>","<em>хохот</em>","<em>грохот</em>","<em>лепет</em>."],"key":"А","review":["Глагол от названия звука","Подбери «рокотать», «хохотать», «грохотать» и «лепетать». Проверь, сохраняются ли звуки существительного в соответствующем глаголе.","От «ропот» получается «роптать» с выпадением второй «о». В остальных парах гласная основы сохраняется."]},{"author":"Б. Иомдин","question":"Какое из этих существительных не может быть одушевлённым?","choices":["<em>тип</em>","<em>лицо</em>","<em>субъект</em>","<em>фрукт</em>","все существительные (А)–(Г) могут быть одушевлёнными."],"key":"Д","review":["Слова для описания человека","Проверь, можно ли употребить каждое слово как обозначение человека. У одного будет переносный разговорный смысл.","«Тип», «лицо» и «субъект» называют людей. «Фрукт» тоже может означать человека, например «я знаю этого фрукта». Все четыре слова бывают одушевлёнными."]},{"author":"С. Бурлак","question":"Какое из этих существительных склоняется не совсем так, как остальные?","choices":["<em>семя</em>","<em>время</em>","<em>имя</em>","<em>племя</em>","все эти существительные склоняются одинаково."],"key":"А","review":["Родительный множественного","Образуй от каждого слова форму с «много». Сравни гласную суффикса перед «н».","Говорят «много имён», «времён», «племён», но «семян». Склонение «семя» отличается этой формой."]},{"author":"Е. Вельмезова","question":"<em>Этот дом. Эта книга. Это письмо.</em> Какие из этих сочетаний слов могут быть не только словосочетаниями, но и двусоставными полными предложениями?","choices":["<em>Этот дом.</em>","<em>Эта книга.</em>","<em>Это письмо.</em>","<em>Этот дом</em> и <em>Эта книга.</em>","никакие."],"key":"В","review":["Сочетание или предложение","Прочитай варианты с паузой после первого слова. Где первое слово может быть самостоятельным подлежащим?","«Это письмо» бывает сочетанием вроде «я прочитал это письмо» или предложением «Это — письмо». В последнем случае «это» указывает на предъявленный предмет."]},{"author":"П. Аркадьев и Н. Валеева","question":"Какое из приведённых слов может обозначать только музыкальный инструмент?","choices":["<em>альт</em>","<em>волынка</em>","<em>барабан</em>","<em>лира</em>","<em>валторна</em>."],"key":"Д","review":["Название инструмента","Попробуй найти дополнительные значения: голос у «альта», монету у «лиры» и переносное выражение у «волынки».","«Валторна» называет только духовой музыкальный инструмент. Остальные варианты употребляются и в других значениях."]},{"author":"Н. Валеева","question":"Даны глагольные формы: <em>бывало</em>, <em>было</em>, <em>бывает</em>, <em>будет</em>. Какие из них могут употребляться в качестве вводных слов?","choices":["только <em>бывало</em> и <em>было</em>","только <em>бывало</em> и <em>бывает</em>","только <em>бывало</em>, <em>было</em> и <em>бывает</em>","только <em>было</em>, <em>бывает</em> и <em>будет</em>","в качестве вводных слов могут употребляться все эти глагольные формы."],"key":"Б","review":["Вводные формы глагола","Вставь варианты со значением «иногда» или «случалось». Проверь, какие можно обособить запятыми.","«Бывало, он заходил» и «Бывает, он заходит» имеют вводные слова. «Было» может быть частицей, «будет» — формой сказуемого."]},{"author":"И. Иткин","question":"У приставки <em>раз-</em> есть вариант <em>разо-</em>, например: <em>развеселить</em>, но <em>разозлить</em>. Какая из следующих приставок не имеет варианта с <em>о</em>?","choices":["<em>без</em>-","<em>над</em>-","<em>под</em>-","<em>от</em>-","все эти приставки имеют варианты с <em>о</em>."],"key":"А","review":["Две формы приставки","Подбери глаголы «надорвать», «подогреть» и «отогнуть». В каждом есть вариант приставки с «о».","У «над-», «под-» и «от-» такие варианты есть. У приставки «без-» варианта «безо-» нет, хотя существует отдельный предлог «безо»."]},{"author":"А. Пиперски","question":"Дан отрывок из романа Ю. Бондарева «Берег»: «<em>— Виноватую голову меч не сечёт, товарищ лейтенант. — Не виноватую, а …, — поправил Никитин. — Виноватую как раз сечёт</em>». Какое слово в этой цитате заменено многоточием?","choices":["<em>винную</em>","<em>невинную</em>","<em>повинную</em>","<em>виновную</em>","<em>провинившуюся</em>."],"key":"В","review":["Слово в пословице","Вспомни традиционную пословицу о мече и человеке, который признаёт вину.","Говорят «Повинную голову меч не сечёт». «Повинная» здесь — признавшая свою вину."]},{"author":"О. Баженова","question":"Учитель написал на доске четыре слова, а потом в каждом стёр несколько первых букв. Получилось вот что: <em>...манн</em>, <em>...мен</em>, <em>...ман</em>, <em>...мен</em>. Какие буквы были стёрты?","choices":["<em>бизнес…</em>, <em>яхтс…</em>, <em>штур…</em>, <em>спортс…</em>","<em>мич…</em>, <em>бизнес…</em>, <em>нор…</em>, <em>спортс…</em>","<em>ос…</em>, <em>бар…</em>, <em>кэб…</em>, <em>нэп…</em>","<em>нор…</em>, <em>нэп…</em>, <em>ту…</em>, <em>кэб…</em>","<em>нор…</em>, <em>яхтс…</em>, <em>нэп…</em>, <em>бар…</em>."],"key":"Д","review":["Начала четырёх слов","Прибавь к каждому обрывку предложенное начало. Проверь число «н» и порядок согласных на стыке.","Получаются «норманн», «яхтсмен», «нэпман», «бармен». Эти слова образуются из начал «нор-», «яхтс-», «нэп-», «бар-»."]},{"author":"Е. Муравенко","question":"Как правильно в современном русском литературном языке? <em>На этих полках около</em>","choices":["<em>восьмиста книг</em>","<em>восьмисот книг</em>","<em>восемьсот книг</em>","<em>восьми сот книг</em>","<em>восьми ста книг.</em>"],"key":"Б","review":["Падеж числительного сотен","«Около» требует родительного. Просклоняй целое числительное и сохрани его слитное написание.","У «восемьсот» родительная форма «восьмисот». Правильно «около восьмисот книг»."]},{"author":"Е. Муравенко","question":"Даны предложения:\n1) <em>О концерте Игорь узнал только вчера.</em>\n2) <em>Он обязательно придёт, только может опоздать.</em>\n3) <em>Все ждали Игоря; только он пришёл, концерт начался.</em>\nВ каких предложениях слово <em>только</em> употреблено в качестве союза?","choices":["во всех","только в 1 и 2","только в 2","только в 2 и 3","только в 3."],"key":"Г","review":["Роли слова «только»","Подставь «лишь», «однако» и «как только» в три предложения. Посмотри, когда слово соединяет части.","В 1 «только» ограничивает время и является частицей. В 2 значит «однако», в 3 — «как только», поэтому в 2 и 3 это союз."]},{"author":"А. Пиперски","question":"Какое из этих слов греческого происхождения не содержит в себе отрицательной приставки <em>ан-</em>?","choices":["<em>анальгин</em>","<em>аноним</em>","<em>анестезия</em>","<em>аналог</em>","<em>анархия</em>."],"key":"Г","review":["Греческое начало «ан»","Проверь, соотносится ли начало слова с отсутствием боли, имени, чувствительности или власти.","«Анальгин», «аноним», «анестезия» и «анархия» имеют отрицательный элемент. «Аналог» происходит от другой греческой приставки «ана-» и означает соответствие."]},{"author":"Е. Муравенко","question":"Даны производные предлоги в сочетании с существительными: 1) <em>благодаря Александру</em>; 2) <em>спустя неделю</em>; 3) <em>несмотря на дождь</em>; 4) <em>включая компьютер</em>. Какие из них в этих выражениях можно воспринять также и как деепричастия?","choices":["все","все, кроме 2","все, кроме 3","только 4","только 1 и 4."],"key":"Д","review":["Предлог и добавочное действие","В двух сочетаниях зависимое существительное можно понять как прямое дополнение к действию «поблагодарить» или «включить».","«Благодаря Александру» может значить «благодаря женщину по имени Александра»: «Александру» винительный. «Включая компьютер» может означать действие включения. Подходят 1 и 4."]},{"author":"Н. Валеева","question":"Даны слова: <em>э…скалатор</em>, <em>э…скиз</em>, <em>э…скимо</em>, <em>э…скорт</em>, <em>э…скулап</em>. Сколько из них на месте пропуска должны иметь букву <em>к</em>?","choices":["четыре","три","два","одно","ни одно."],"key":"Д","review":["Буква после начальной «э»","Произнеси каждое слово и проверь его обычное написание. На месте пропуска может и не быть буквы.","Пишут «эскалатор», «эскиз», «эскимо», «эскорт», «эскулап». Между «э» и «с» ни в одном из них нет «к»."]},{"author":"С. Бурлак","question":"Во всех приведённых ниже парах слов, кроме одной, второе слово содержит только те звуки, которые есть в первом. Кроме какой?","choices":["<em>плёс</em> — <em>соль</em>","<em>шлюпка</em> — <em>пулька</em>","<em>лёд</em> — <em>толь</em>","<em>юбка</em> — <em>буй</em>","<em>полюс</em> — <em>пульс</em>."],"key":"Г","review":["Сравнение звуков в паре","Сравни произношение, особенно согласные перед глухими. Одна буква может обозначать разные звуки.","В «юбка» перед [к] буква «б» произносится как [п]. В «буй» слышится звонкий [б], которого в первом слове нет."]},{"author":"Н. Валеева","question":"Какого устойчивого оборота не существует?","choices":["не по карману","не по средствам","не по зубам","не по силе","не по себе."],"key":"Г","review":["Устойчивый оборот и число","Подбери к каждому выражению пример. Если форма слова кажется непривычной, проверь, не говорят ли во множественном числе.","Нормативный оборот — «не по силам». «Не по силе» не является тем устойчивым сочетанием, какое проверяет задача."]},{"author":"Л. Фёдорова","question":"В каких предложениях на месте прочерка обязательно требуется запятая?\n1) <em>Между тем_ гости начали расходиться.</em>\n2) <em>Между прочим_ он упомянул о результатах экзаменов.</em>\n3) <em>Как бы между прочим_ она спросила о дне рождения Миши.</em>\n4) <em>Между делом_ бабушка успевала успокоить внучат.</em>","choices":["во всех","ни в каких","во всех, кроме 4","только в 2","только в 1 и 2."],"key":"Б","review":["Запятая после оборота","Отличай обязательную запятую от той, которая зависит от прочтения. «Между прочим» можно понять как «кстати» или «мимоходом».","В 2 при вводном прочтении запятая возможна. При значении «мимоходом» её нет. В остальных фразах данные обороты также не требуют запятой."]},{"author":"Н. Валеева","question":"Вот отрывок из стихотворения Г. Державина «Буря»:\n<em>Судно, по морю носимо,\nРеет между черных волн;\nБелы горы идут мимо,\nВ шуме их — надежд я полн.</em>\nСколько в нём имён прилагательных?","choices":["одно","два","три","четыре","пять."],"key":"В","review":["Прилагательные у Державина","Найди слова, которые обозначают признак предмета. Учти краткие прилагательные и отдели их от причастия «носимо».","Прилагательные — «черных», «белы» и «полн». «Носимо» связано с действием «носить» и является кратким страдательным причастием."]},{"author":"Н. Грехнева","question":"В какой из фраз выделенное слово написано с ошибкой?","choices":["<em>А всего взяла зазнобушка бирюзовый <strong>перстенёк</strong>.</em> (Н. Некрасов)","<em>Епископ носит на груди <strong>наперстный</strong> крест.</em>","<em>Чтобы не уколоться иголкой, наденьте <strong>напёрсток</strong>.</em>","<em>Но есть и Божий суд, <strong>наперсники</strong> разврата!</em> (М. Лермонтов)","Во всех фразах выделенные слова написаны правильно."],"key":"Б","review":["Крест и старое слово","Вспомни, где епископ носит крест. Старое слово для этой части тела отличается от слова «перст», обозначающего палец.","Правильно «наперсный крест», от «перси» — грудь. В форме «наперстный» лишняя «т»."]},{"author":"И. Иткин и И. Семушин","question":"Новые, недавно синтезированные химические элементы, ещё не имеющие официальных названий, получают специальные временные наименования. Какой порядковый номер в таблице Менделеева имеет один из таких элементов — унунбий?","choices":["110","111","112","120","122."],"key":"В","review":["Код в названии элемента","Раздели «унунбий» на части «ун», «ун» и «би». В систематическом названии им соответствуют отдельные цифры.","«Ун» означает 1, «би» — 2. Три части подряд кодируют 112."]},{"author":"Б. Иомдин","question":"Смешные оговорки, получившиеся случайной перестановкой одного или нескольких звуков, называют спунеризмами. Данные ниже выражения часто приводят в качестве примеров спунеризмов. Однако на самом деле лишь одно из них строго соответствует определению. Какое?","choices":["<em>подогрели, обобрали</em>","<em>вагоноуважаемый глубокоуважатый</em>","<em>внимать обращение</em>","<em>посетителей не будят</em>","<em>собачья кусака</em>."],"key":"А","review":["Перестановка звуков","Попробуй восстановить исходное выражение и проверить, можно ли точно поменять местами два фрагмента, ничего не добавляя.","«Подогрели, обобрали» получается из «обогрели, подобрали» обменом начальных частей «об» и «под». Только здесь получается перестановка без изменения набора звуков."]},{"author":"Е. Муравенко","question":"В разных формах русских слов нередко можно встретить подряд две буквы <em>е</em>, например: <em>сильнее</em>, <em>зимнее</em>, <em>сердцеед</em>. А какие удвоенные гласные буквы не встречаются в исконно русских словах?","choices":["<em>аа</em>","<em>уу</em>","<em>ии</em>","<em>оо</em>","все эти удвоенные гласные встречаются в исконно русских словах."],"key":"Д","review":["Две гласные на стыке","Поищи одинаковые буквы между приставкой и корнем или между частями сложного слова.","Есть «заахать», «двуустка», «прииск» и «пообедать». В них встречаются «аа», «уу», «ии» и «оо»."]},{"author":"И. Иткин","question":"Даны некоторые польские глаголы и их переводы на русский язык: zdać — <em>сдать</em>; znosić — <em>сносить</em>, <em>износить</em>; zryć — <em>изрыть</em>. Какой из следующих русских глаголов заимствован из польского языка?\nПримечание. <em>ć</em> читается как очень мягко произнесённое русское <em>ть</em>, <em>y</em> — как русское <em>ы</em>.","choices":["<em>создать</em>","<em>воздать</em>","<em>позволить</em>","<em>провозгласить</em>","<em>низвести</em>."],"key":"В","review":["След польской приставки","Посмотри, как польская начальная «z-» передаётся по-русски в примерах. Ищи глагол, сохранивший польский облик.","«Позволить» заимствовано из польского «pozwolić». В нём слышна та же «z», что и в данных польских глаголах."]}], {"year":2009,"grade":"10-11","tasksFile":"10-11.pdf","answersFile":"10-11-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2009.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
